function cutZeroRuns(head: ListNode | null): ListNode | null {
  const dummy = new ListNode(0, head);
  let prev = dummy;
  while (prev.next) {
    let sum = 0, cutEnd: ListNode | null = null;
    for (let q: ListNode | null = prev.next; q; q = q.next) {
      sum += q.val;
      if (sum === 0) cutEnd = q;
    }
    if (cutEnd) prev.next = cutEnd.next;
    else prev = prev.next;
  }
  return dummy.next;
}

