function cutZeroRuns(head: ListNode | null): ListNode | null {
  const dummy = new ListNode(0, head);
  const last = new Map<number, ListNode>();
  let sum = 0;
  for (let node: ListNode | null = dummy; node; node = node.next) {
    sum += node.val;
    last.set(sum, node);
  }
  sum = 0;
  for (let node: ListNode | null = dummy; node; node = node.next) {
    sum += node.val;
    node.next = last.get(sum)!.next;
  }
  return dummy.next;
}

